  1	package jobs
  2	
  3	import "time"
  4	
  5	func (j *Service) Cancel(id int64, now time.Time) error {
  6		r, e := j.S.DB.Exec(`UPDATE jobs SET state='cancelled',event_at=$2,finished_at=$2 WHERE id=$1 AND state NOT IN ('succeeded','dead','cancelled')`, id, now)
  7		if e = Changed(r, e); e != nil {
  8			return e
  9		}
 10		return j.Notify(id, now)
 11	}
 12	func (j *Service) Retry(id int64, now time.Time) error {
 13		r, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$2,attempts=0,run_at=$2,finished_at=NULL WHERE id=$1 AND state='dead'`, id, now)
 14		return Changed(r, e)
 15	}
 16	package jobs
 17	
 18	import (
 19		"encoding/json"
 20		"time"
 21	)
 22	
 23	func (j *Service) Ack(id int64, token string, result any, now time.Time) error {
 24		b, _ := json.Marshal(result)
 25		r, e := j.S.DB.Exec(`UPDATE jobs SET state='succeeded',event_at=$3,result=$2,finished_at=$3,attempts=attempts+1 WHERE id=$1 AND state='leased' AND lease_token=$4 AND lease_expires_at > $3`, id, string(b), now, token)
 26		if e = Changed(r, e); e != nil {
 27			return e
 28		}
 29		_, e = j.S.DB.Exec(`INSERT INTO attempts SELECT id,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),leased_by,leased_at,$2,'succeeded','' FROM jobs WHERE id=$1`, id, now)
 30		if e != nil {
 31			return e
 32		}
 33		return j.Notify(id, now)
 34	}
 35	package jobs
 36	
 37	import "time"
 38	
 39	func (j *Service) Nack(id int64, token, message string, retry bool, delay *int, now time.Time) error {
 40		tx, e := j.S.DB.Begin()
 41		if e != nil {
 42			return e
 43		}
 44		defer tx.Rollback()
 45		var attempts, max, base, cap int
 46		var kind string
 47		var worker int64
 48		e = tx.QueryRow(`SELECT j.attempts+1,j.max_attempts,q.backoff_kind,q.backoff_base,COALESCE(q.backoff_max,0),j.leased_by FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1 AND j.state='leased' AND j.lease_token=$2 AND j.lease_expires_at > $3 FOR UPDATE OF j`, id, token, now).Scan(&attempts, &max, &kind, &base, &cap, &worker)
 49		if e != nil {
 50			return e
 51		}
 52		state := "retry_wait"
 53		if !retry || attempts >= max {
 54			state = "dead"
 55		}
 56		wait := Backoff(kind, base, attempts, cap)
 57		if delay != nil {
 58			wait = time.Duration(*delay) * time.Second
 59		}
 60		_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$6,attempts=$3,last_error=$4,run_at=$5,finished_at=CASE WHEN $2='dead' THEN $6::timestamptz ELSE NULL END,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1`, id, state, attempts, message, now.Add(wait), now)
 61		if e != nil {
 62			return e
 63		}
 64		_, e = tx.Exec(`INSERT INTO attempts SELECT $1,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$2,leased_at,$3,'failed',$4 FROM jobs WHERE id=$1`, id, worker, now, message)
 65		if e != nil {
 66			return e
 67		}
 68		if e = tx.Commit(); e != nil {
 69			return e
 70		}
 71		if state == "dead" {
 72			return j.Notify(id, now)
 73		}
 74		return nil
 75	}
 76	package jobs
 77	
 78	import "time"
 79	
 80	func (j *Service) Expire(now time.Time) error {
 81	
 82		tx, e := j.S.DB.Begin()
 83		if e != nil {
 84			return e
 85		}
 86		defer tx.Rollback()
 87		rows, e := tx.Query(`SELECT id,attempts+1,max_attempts,leased_by FROM jobs WHERE state='leased' AND lease_expires_at <= $1 FOR UPDATE SKIP LOCKED`, now)
 88		if e != nil {
 89			return e
 90		}
 91		type expired struct {
 92			id, worker int64
 93			n, max     int
 94		}
 95		batch := []expired{}
 96		for rows.Next() {
 97			var r expired
 98			if e = rows.Scan(&r.id, &r.n, &r.max, &r.worker); e != nil {
 99				rows.Close()
100				return e
101			}
102			batch = append(batch, r)
103		}
104		e = rows.Err()
105		rows.Close()
106		if e != nil {
107			return e
108		}
109		dead := []int64{}
110		for _, r := range batch {
111			state := "queued"
112			if r.n >= r.max {
113				state = "dead"
114				dead = append(dead, r.id)
115			}
116			_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$4,attempts=$3,last_error='lease expired',run_at=$4,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL,finished_at=CASE WHEN $2='dead' THEN $4::timestamptz ELSE NULL END WHERE id=$1`, r.id, state, r.n, now)
117			if e != nil {
118				return e
119			}
120			_, e = tx.Exec(`INSERT INTO attempts SELECT $1,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$2,leased_at,$3,'expired','lease expired' FROM jobs WHERE id=$1`, r.id, r.worker, now)
121			if e != nil {
122				return e
123			}
124		}
125		if e = tx.Commit(); e != nil {
126			return e
127		}
128		for _, id := range dead {
129			if e = j.Notify(id, now); e != nil {
130				return e
131			}
132		}
133		return nil
134	}
