136	func (j *Service) Promote(now time.Time) error {
137		_, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$1 WHERE state IN ('scheduled','retry_wait') AND run_at <= $1`, now)
138		return e
139	}
140	func (j *Service) Retain(now time.Time) error {
141		_, e := j.S.DB.Exec(`WITH removed AS (DELETE FROM jobs j USING queues q WHERE j.queue_id=q.id AND j.state IN ('succeeded','cancelled','dead') AND extract(epoch FROM $1::timestamptz - j.finished_at) / 3600 > q.retention_hours RETURNING j.*) INSERT INTO job_events(job_id,namespace_id,at,event,queue,worker,attempt) SELECT r.id,r.namespace_id,$1,'retained',q.name,r.leased_by,r.attempts FROM removed r JOIN queues q ON q.id=r.queue_id`, now)
142		return e
143	}
144	// Package clock controls API semantic time only. Process and network timers stay real.
145	package clock
146	
147	import (
148		"fmt"
149		"sync"
150		"time"
151	)
152	
153	type Clock struct {
154		mu    sync.RWMutex
155		fixed *time.Time
156	}
157	
158	func (c *Clock) Now() time.Time {
159		c.mu.RLock()
160		defer c.mu.RUnlock()
161		if c.fixed != nil {
162			return *c.fixed
163		}
164		return time.Now().UTC()
165	}
166	func (c *Clock) Change(action string, at time.Time, seconds float64) (time.Time, error) {
167		c.mu.Lock()
168		defer c.mu.Unlock()
169		now := time.Now().UTC()
170		if c.fixed != nil {
171			now = *c.fixed
172		}
173		switch action {
174		case "reset":
175			c.fixed = nil
176			return now, nil
177		case "set":
178			if at.IsZero() {
179				return now, fmt.Errorf("at required")
180			}
181			now = at.UTC()
182		case "advance":
183			d := seconds * float64(time.Second)
184			if d >= float64(1<<63-1) || d <= -float64(1<<63-1) {
185				return now, fmt.Errorf("advance out of range")
186			}
187			now = now.Add(time.Duration(d))
188		default:
189			return now, fmt.Errorf("unknown clock action")
190		}
191		c.fixed = &now
192		return now, nil
193	}

