  1	package jobs
  2	
  3	import (
  4		"crypto/rand"
  5		"database/sql"
  6		"encoding/hex"
  7		"encoding/json"
  8		"fmt"
  9		"github.com/lib/pq"
 10		"math"
 11		"queuelet/internal/store"
 12		"time"
 13	)
 14	
 15	type Service struct{ S *store.Store }
 16	
 17	func Token() string { b := make([]byte, 16); rand.Read(b); return hex.EncodeToString(b) }
 18	
 19	// MaxSeconds bounds every seconds-valued input so that now+seconds never
 20	// leaves time.Duration's range (about 292 years).
 21	const MaxSeconds = math.MaxInt32
 22	
 23	// DefaultMaxSeconds caps each retry wait of a queue without backoff.max_seconds.
 24	const DefaultMaxSeconds = 3600
 25	
 26	// Backoff is the wait before retry attempt+1. It saturates at the queue's cap
 27	// (maxSeconds > 0), or at DefaultMaxSeconds or the base if that is larger.
 28	func Backoff(kind string, base, attempt, maxSeconds int) time.Duration {
 29		limit := float64(max(DefaultMaxSeconds, base))
 30		if maxSeconds > 0 {
 31			limit = float64(maxSeconds)
 32		}
 33		steps := float64(attempt)
 34		if kind != "linear" {
 35			steps = math.Exp2(float64(attempt - 1))
 36		}
 37		return time.Duration(min(float64(base)*steps, limit) * float64(time.Second))
 38	}
 39	
 40	const LeaseOrder = "priority DESC, created_at, id"
 41	
 42	func (j *Service) Lease(q, w int64, max int, now time.Time) ([]map[string]any, error) {
 43		tx, e := j.S.DB.Begin()
 44		if e != nil {
 45			return nil, e
 46		}
 47		defer tx.Rollback()
 48		var sec int
 49		var paused bool
 50		if e = tx.QueryRow(`SELECT lease_seconds,paused FROM queues WHERE id=$1`, q).Scan(&sec, &paused); e != nil {
 51			return nil, e
 52		}
 53		if paused {
 54			return []map[string]any{}, nil
 55		}
 56		var kinds pq.StringArray
 57		if e = tx.QueryRow(`SELECT kinds FROM workers WHERE id=$1`, w).Scan(&kinds); e != nil {
 58			return nil, e
 59		}
 60		rows, e := tx.Query(`SELECT id FROM jobs WHERE queue_id=$1 AND state='queued' AND kind=ANY($2) ORDER BY `+LeaseOrder+` LIMIT $3 FOR UPDATE SKIP LOCKED`, q, kinds, max)
 61		if e != nil {
 62			return nil, e
 63		}
 64		ids := []int64{}
 65		for rows.Next() {
 66			var id int64
 67			rows.Scan(&id)
 68			ids = append(ids, id)
 69		}
 70		rows.Close()
 71		out := []map[string]any{}
 72		for _, id := range ids {
 73			token := Token()
 74			var payload []byte
 75			var kind string
 76			var attempt int
 77			e = tx.QueryRow(`UPDATE jobs SET state='leased',leased_at=$5,event_at=$5,leased_by=$2,lease_token=$3,lease_expires_at=$4 WHERE id=$1 RETURNING kind,payload,attempts+1`, id, w, token, now.Add(time.Duration(sec)*time.Second), now).Scan(&kind, &payload, &attempt)
 78			if e != nil {
 79				return nil, e
 80			}
