 17	func Token() string { b := make([]byte, 16); rand.Read(b); return hex.EncodeToString(b) }
 18	
 19	// MaxSeconds bounds every seconds-valued input so that now+seconds never
 20	// leaves time.Duration's range (about 292 years).
 21	const MaxSeconds = math.MaxInt32
 22	
 23	// DefaultMaxSeconds caps each retry wait of a queue without backoff.max_seconds.
 24	const DefaultMaxSeconds = 3600
 25	
 26	// Backoff is the wait before retry attempt+1. It saturates at the queue's cap
 27	// (maxSeconds > 0), or at DefaultMaxSeconds or the base if that is larger.
 28	func Backoff(kind string, base, attempt, maxSeconds int) time.Duration {
 29		limit := float64(max(DefaultMaxSeconds, base))
 30		if maxSeconds > 0 {
 31			limit = float64(maxSeconds)
 32		}
 33		steps := float64(attempt)
 34		if kind != "linear" {
 35			steps = math.Exp2(float64(attempt - 1))
 36		}
 37		return time.Duration(min(float64(base)*steps, limit) * float64(time.Second))
 38	}
