     1	package schedule
     2	
     3	import (
     4		"database/sql"
     5		"fmt"
     6		"github.com/robfig/cron/v3"
     7		"queuelet/internal/store"
     8		"time"
     9	)
    10	
    11	var parser = cron.NewParser(cron.Minute | cron.Hour | cron.Dom | cron.Month | cron.Dow)
    12	
    13	func Next(expression, zone string, offset int, after time.Time) (time.Time, error) {
    14		s, e := parser.Parse(expression)
    15		if e != nil {
    16			return time.Time{}, e
    17		}
    18		loc, e := time.LoadLocation(zone)
    19		if e != nil {
    20			return time.Time{}, e
    21		}
    22		return s.Next(after.In(loc)), nil
    23	}
    24	func Offset(zone string, now time.Time) (int, error) {
    25		loc, e := time.LoadLocation(zone)
    26		if e != nil {
    27			return 0, e
    28		}
    29		_, offset := now.In(loc).Zone()
    30		return offset, nil
    31	}
    32	func Fire(s *store.Store, now time.Time) error {
    33		rows, e := s.Rows(`SELECT id FROM schedules WHERE enabled AND next_run_at <= $1 ORDER BY id`, now)
    34		if e != nil {
    35			return e
    36		}
    37		for _, r := range rows {
    38			if e = fireOne(s, r["id"], now); e != nil {
    39				return e
    40			}
    41		}
    42		return nil
